import { auditEntry } from "../src/audit.ts";

test("audit entry has the five fields auditors need", () => {
  const req = {
    method: "POST",
    path: "/admin/fleet/image",
    headers: { "x-request-id": "req_123", "x-forwarded-for": "203.0.113.42" },
    actor: "user_marin",
  };
  const entry = auditEntry(req, "fleet.image.update", new Date("2026-11-17T10:00:00Z"));

  assert.equal(entry.actor, "user_marin");
  assert.equal(entry.action, "fleet.image.update");
  assert.equal(entry.timestamp, "2026-11-17T10:00:00.000Z");
  assert.equal(entry.outcome, "success");
  assert.equal(entry.path, "/admin/fleet/image");
});

test("audit entry records impersonation separately from actor", () => {
  const req = {
    method: "DELETE",
    path: "/admin/tokens/revoke",
    headers: { "x-impersonated-as": "user_customer" },
    actor: "user_support",
  };
  const entry = auditEntry(req, "token.revoke");

  assert.equal(entry.actor, "user_support");
  assert.equal(entry.impersonated_as, "user_customer");
});

